package com.ripplenexus.salespilot.target.application;

import com.ripplenexus.salespilot.core.exception.ResourceNotFoundException;
import com.ripplenexus.salespilot.employee.infrastructure.EmployeeRepository;
import com.ripplenexus.salespilot.notification.application.NotificationService;
import com.ripplenexus.salespilot.target.domain.Target;
import com.ripplenexus.salespilot.target.infrastructure.TargetRepository;
import jakarta.transaction.Transactional;

import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Service
@Transactional
public class TargetService {
    private static final Logger log = LoggerFactory.getLogger(TargetService.class);
    private final TargetRepository targetRepository;
    private final EmployeeRepository employeeRepository;
    private final NotificationService notificationService;
    private final com.ripplenexus.salespilot.core.email.EmailService emailService;

    public void updateRevenueProgress(UUID employeeId, BigDecimal amount) {
        LocalDate today = LocalDate.now();
        List<Target> activeTargets = targetRepository.findActiveRevenueTargets(employeeId, today);
        activeTargets.forEach(target -> {
            target.setAchievedValue(target.getAchievedValue().add(amount));
            targetRepository.save(target);
            // Check if target achieved
            if (target.getAchievedValue().compareTo(target.getTargetValue()) >= 0) {
                var employee = target.getEmployee();
                notificationService.notifyTargetAchieved(employee.getUser(), target.getPeriod().name().toLowerCase(), "100");
                emailService.sendTargetAchievedEmail(employee.getWorkEmail(), employee.getFirstName(), target.getPeriod().name().toLowerCase());
            }
            log.debug("Target progress updated for employee: {} | Added: {}", employeeId, amount);
        });
    }

    public List<Target> getByEmployee(UUID employeeId) {
        return targetRepository.findByEmployeeId(employeeId);
    }

    public List<Target> getAllTargets() {
        return targetRepository.findAll();
    }

    public Target createTarget(UUID employeeId, Target.TargetPeriod period, Target.TargetType type, BigDecimal targetValue, LocalDate start, LocalDate end) {
        var employee = employeeRepository.findById(employeeId).orElseThrow(() -> new ResourceNotFoundException("Employee", employeeId));
        Target target = new Target();
        target.setEmployee(employee);
        target.setType(type);
        target.setPeriod(period);
        target.setPeriodStart(start);
        target.setPeriodEnd(end);
        target.setTargetValue(targetValue);
        target.setAchievedValue(BigDecimal.ZERO);
        target.setCurrency("INR");
        return targetRepository.save(target);
    }

    @java.lang.SuppressWarnings("all")
    
    public TargetService(final TargetRepository targetRepository, final EmployeeRepository employeeRepository, final NotificationService notificationService, final com.ripplenexus.salespilot.core.email.EmailService emailService) {
        this.targetRepository = targetRepository;
        this.employeeRepository = employeeRepository;
        this.notificationService = notificationService;
        this.emailService = emailService;
    }
}
